internal final class NDXUnitOfMeasureConversion_tbl_EventHandler
{

}

Method.Source:
/// <summary>
/// Modified field event handler
/// </summary>
/// <param name="sender">sender record</param>
/// <param name="e">Data event args</param>
[DataEventHandler(tableStr(UnitOfMeasureConversion), DataEventType::ModifiedField)]
public static void UnitOfMeasureConversion_onModifiedField(Common sender, DataEventArgs e)
{
    UnitOfMeasureConversion unitOfMeasureConversion = sender as UnitOfMeasureConversion;
    ModifyFieldEventArgs event = e as ModifyFieldEventArgs;
    FieldId fieldId = event.parmFieldId();

    boolean lOK = true;
    NDXUnitConvert oUnitConvert;
    ;

    switch(fieldId)
    {
        case fieldnum(UnitOfMeasureConversion, NDXUnitConvertPrevLevel):
            // Falls Level == 1 kann nicht von der vorherigen Stufe selektiert werden
            if (unitOfMeasureConversion.NDXUnitConvertPrevLevel == NoYes::Yes && unitOfMeasureConversion.NDXUnitLevel == 1)
            {
                Warning("@NDX:NDXUnitConvertCheckInfoTxt11");    // Für diese Einstellung muss die Verpackungsstufe > 1 sein!
                unitOfMeasureConversion.NDXUnitConvertPrevLevel = NoYes::No;
                lOK = false;
            }
            break;
    }
    if (!lOK)
    {
        return;
    }

    switch(fieldId)
    {
        case fieldnum(UnitOfMeasureConversion, NDXUnitConvertPrevLevel):
        case fieldnum(UnitOfMeasureConversion, NDXFixedValues):
        case fieldnum(UnitOfMeasureConversion, ToUnitOfMeasure):
        case fieldnum(UnitOfMeasureConversion, NDXHeight):
        case fieldnum(UnitOfMeasureConversion, NDXLength):
        case fieldnum(UnitOfMeasureConversion, NDXWidth):
            oUnitConvert = NDXUnitConvert::constructor();
            oUnitConvert.checkUnitConvertWeight(unitOfMeasureConversion, false, false);
            unitOfMeasureConversion.initFromUnitConvert(oUnitConvert.parmUnitConvertTmp());
            break;

        case fieldnum(UnitOfMeasureConversion, NDXUnitMaxQty):
            if (!unitOfMeasureConversion.NDXUnitMinQty)
            {
                unitOfMeasureConversion.NDXUnitMinQty = unitOfMeasureConversion.NDXUnitMaxQty;
            }
            break;
    }
}
